const CACHE='aerostat-shell-v29';
const SHELL=['./','./index.html','./style.css','./theme.css','./app.mjs','./confirm-action.mjs','./flight-assist.mjs','./flight-export.mjs','./race-core.mjs','./races/kapadokya-2026.json','./race-import.mjs','./race-layers.mjs','./flight-navigation.mjs','./core.mjs','./global-coordinates.mjs','./regional-reference.mjs','./wind-profile.mjs','./barometer.mjs','./pdf-reader.mjs','./competitions.json','./samples/slovenia-flight1.json','./assets/targetnav-logo-dark.png','./assets/targetnav-icon-dark.png','./assets/targetnav-logo-light.png','./assets/targetnav-icon-light.png','./assets/targetnav-app-180.png','./assets/targetnav-app-192.png','./assets/targetnav-app-512.png','./manifest.webmanifest','./vendor/leaflet.js','./vendor/leaflet.css','./vendor/proj4.js','./vendor/geodesic.js','./vendor/index.js','./vendor/pdf.mjs','./vendor/pdf.worker.mjs','./vendor/tesseract.min.js','./vendor/ocr/worker.min.js','./vendor/ocr/tesseract-core-lstm.wasm.js','./vendor/ocr/tesseract-core-simd-lstm.wasm.js','./vendor/ocr/eng.traineddata','./vendor/ocr/tur.traineddata','./vendor/images/layers.png','./vendor/images/layers-2x.png','./vendor/images/marker-icon.png','./vendor/images/marker-icon-2x.png','./vendor/images/marker-shadow.png'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(async c=>{await c.addAll(SHELL);await c.put('./offline-ready.json',new Response(JSON.stringify({ready:true,version:29}),{headers:{'Content-Type':'application/json'}}));}).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('aerostat-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>r.ok?r:caches.match(e.request).then(c=>c||r)).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
